public void Main()
{
    try
    {
        var filePath = Dts.Variables["User::ExcelFilePath"].Value.ToString();
        var sheetName = GetSheetName(filePath);

        Dts.Variables["User::SheetName"].Value = sheetName;
        Dts.TaskResult = (int) ScriptResults.Success;
    } catch (ScriptException e) {
        Dts.Events.FireError(0, "ERROR", e.Message, null, 0);
        Dts.TaskResult = (int)ScriptResults.Failure;
    }
}

private string GetSheetName(string filePath)
{
    if (! File.Exists(filePath))
        throw new ScriptException($"The file '{filePath}' cannot be found");

    var connStr = $"Provider=Microsoft.ACE.OLEDB.12.0; Data Source={filePath}; Extended Properties='Excel 12.0;HDR=YES;IMEX=1';";

    using var conn = new OleDbConnection(connStr);
    try {
        conn.Open();
    } catch (Exception e) {
        throw new ScriptException($"Opening OLEDB connection failed: {e.Message}", e);
    }

    var dt = conn.GetOleDbSchemaTable(OleDbSchemaGuid.Tables, null);
    if (dt.Rows.Count < 1)
        throw new ScriptException($"Reading OLE schema failed!");

    return dt.Rows[0]["TABLE_NAME"].ToString();
}
